<?php

namespace Camaleaun\Eject;

use WP_CLI;
use WP_CLI\Utils;

/**
 * Writes the CI/CD that rebuilds the site from blueprint.json and deploys it
 * over SSH: deploy/deploy.php (WP-CLI `build` and `deploy`), deploy/deployignore,
 * deploy/README.md and the provider's pipeline file.
 */
class Pipeline {

	/**
	 * Texts older versions wrote at the top of the generated files: still recognized, so those files
	 * are regenerated (and lose the text).
	 */
	const LEGACY_MARKERS = array( 'Generated file: may be rewritten', 'Generated by wp eject', '<!-- generated' );

	/**
	 * Whether wp eject wrote this file, so a new run may regenerate it. The generated files carry no
	 * "generated" text and no tool name, on purpose, so they are recognized by their content: the
	 * whitelist of the .gitignore, the WordPress coding standards header of the .editorconfig, and
	 * `--require=deploy/deploy.php` (deploy.php, the CI file and both READMEs).
	 *
	 * TODO: if a visible credit is ever wanted, make it an option (e.g. --attribution, or an
	 * `attribution:` key in deploy/config.yml) that adds a "Generated by wp eject (<url>)" line.
	 */
	public static function is_generated( $path ) {
		$content = (string) file_get_contents( $path );
		foreach ( self::LEGACY_MARKERS as $marker ) {
			if ( false !== strpos( substr( $content, 0, 4096 ), $marker ) ) {
				return true;
			}
		}
		switch ( basename( $path ) ) {
			case '.gitignore':
				return false !== strpos( $content, "\n!/blueprint.json\n" ) && false !== strpos( $content, "\n/*\n" );
			case '.editorconfig':
				return false !== strpos( $content, 'make.wordpress.org/core/handbook/coding-standards' );
			default:
				return false !== strpos( $content, '--require=deploy/deploy.php' );
		}
	}

	/**
	 * Drops the header an older version wrote at the top of a file the user owns (deploy/deployignore): the
	 * rest of the file is theirs and stays.
	 *
	 * @return bool True when the file was changed.
	 */
	public static function strip_legacy_header( $file ) {
		$lines = explode( "\n", (string) file_get_contents( $file ) );
		foreach ( self::LEGACY_MARKERS as $marker ) {
			if ( false !== strpos( $lines[0], $marker ) ) {
				array_shift( $lines );
				if ( isset( $lines[0] ) && '#' === trim( $lines[0] ) ) {
					array_shift( $lines );
				}
				file_put_contents( $file, implode( "\n", $lines ) );
				return true;
			}
		}
		return false;
	}

	/** Playground CLI pinned in deploy/deploy.php (override with PLAYGROUND_CLI). */
	const PLAYGROUND_VERSION = '3.1.64';

	const NAMES = array(
		'github'    => 'GitHub Actions',
		'gitlab'    => 'GitLab CI/CD',
		'bitbucket' => 'Bitbucket Pipelines',
	);

	/** Provider => [Mustache template, file written in the repository]. */
	const PROVIDERS = array(
		'github'    => array( 'github.mustache', '.github/workflows/deploy.yml' ),
		'gitlab'    => array( 'gitlab.mustache', '.gitlab-ci.yml' ),
		'bitbucket' => array( 'bitbucket.mustache', 'bitbucket-pipelines.yml' ),
	);

	const DELETE_MODES = array( 'mirror', 'packages', 'none' );

	/** @var Site */
	private $site;
	/** @var string */
	private $provider;
	/** @var string */
	private $branch;
	/** @var string */
	private $delete;
	/** @var string */
	private $vendor_path;
	/** @var bool */
	private $overwrite;
	/** @var string */
	private $staging_branch;

	/** Yours: written only when missing, never overwritten (not even with --overwrite-ci). */
	const CONFIG = 'deploy/config.yml';

	/** Edited by the project, so written once like the config: a new run never overwrites them. */
	const YOURS = array( 'deploy/config.yml', 'deploy/deployignore' );

	public function __construct( Site $site, $provider, $branch, $delete, $vendor_path, $overwrite, $staging_branch = 'staging' ) {
		$this->site           = $site;
		$this->provider       = $provider;
		$this->staging_branch = $staging_branch;
		$this->branch         = $branch;
		$this->delete         = $delete;
		$this->vendor_path    = trim( $vendor_path, '/' );
		$this->overwrite      = (bool) $overwrite;
	}

	/** @var string[] rsync patterns of files packages write at runtime (known.yml "added"). */
	private $protected = array();

	/** Known runtime files: never copied, never deleted on the server. */
	public function protect( array $patterns ) {
		$this->protected = $patterns;
	}

	/** The provider's CI file, relative to the repository root. */
	public function ci_file() {
		return self::PROVIDERS[ $this->provider ][1];
	}

	public function provider() {
		return $this->provider;
	}

	/** Validates the options; called before anything is verified. */
	public static function validate( $provider, $branch, $delete, $staging_branch = 'staging' ) {
		if ( ! isset( self::PROVIDERS[ $provider ] ) ) {
			WP_CLI::error( '--git-provider is required: github, gitlab or bitbucket (or --no-ci to write no CI/CD).' );
		}
		if ( ! in_array( $delete, self::DELETE_MODES, true ) ) {
			WP_CLI::error( '--deploy-delete must be mirror, packages or none.' );
		}
		if ( ! preg_match( '#^[A-Za-z0-9._/-]+$#', $branch ) ) {
			WP_CLI::error( "--git-deploy-branch is not a valid branch name: {$branch}" );
		}
		if ( ! preg_match( '#^[A-Za-z0-9._/-]+$#', $staging_branch ) || $staging_branch === $branch ) {
			WP_CLI::error( "--git-staging-branch must be a valid branch name other than --git-deploy-branch: {$staging_branch}" );
		}
	}

	/**
	 * Every file of the pipeline.
	 *
	 * @return array<string,string> Relative path => content.
	 */
	public function files() {
		// Same rendering as `wp scaffold`: Mustache templates in templates/.
		$templates                 = dirname( __DIR__ ) . '/templates/';
		list( $template, $target ) = self::PROVIDERS[ $this->provider ];
		$data                      = array(
			'branch'             => $this->branch,
			'staging_branch'     => $this->staging_branch,
			'deploy_delete'      => $this->delete,
			'vendor_path'        => $this->vendor_path,
			'playground_version' => self::PLAYGROUND_VERSION,
			'ci_file'            => $target,
			'provider_name'      => self::NAMES[ $this->provider ],
			$this->provider      => true,
		);

		return array(
			'deploy/deploy.php'   => Utils\mustache_render( $templates . 'deploy-php.mustache', $data ),
			self::CONFIG          => Utils\mustache_render( $templates . 'config-yml.mustache', $data ),
			'deploy/deployignore' => $this->deployignore(),
			'deploy/README.md'    => Utils\mustache_render( $templates . 'deploy-readme.mustache', $data ),
			$target               => Utils\mustache_render( $templates . $template, $data ),
		);
	}

	/**
	 * Writes the pipeline into the site (--no-bundle). A file that exists and was
	 * not generated by wp eject is left alone (warning) unless --overwrite-ci.
	 *
	 * @return array<string,string> Relative path => "written" | "kept (…)".
	 */
	public function write() {
		$result = array();
		foreach ( $this->files() as $path => $content ) {
			$file = $this->site->root . $path;
			if ( in_array( $path, self::YOURS, true ) && is_file( $file ) ) {
				$result[ $path ] = 'kept (yours)';
				continue;
			}
			$state = 'written';
			if ( is_file( $file ) && ! $this->overwrite && ! self::is_generated( $file ) ) {
				$blocker = Git::overwrite_blocker( $this->site->root, $path );
				if ( '' !== $blocker ) {
					WP_CLI::warning( "{$path} exists and was not generated by wp eject, and {$blocker}: left as is (use --overwrite-ci to replace it)." );
					$result[ $path ] = 'kept (exists, not generated by wp eject)';
					continue;
				}
				$state = 'written (replaced: git has the previous version)';
			}
			if ( ! is_dir( dirname( $file ) ) ) {
				mkdir( dirname( $file ), 0755, true );
			}
			file_put_contents( $file, $content );
			$result[ $path ] = $state;
		}
		return $result;
	}

	/**
	 * Adds the pipeline to a bundle.
	 *
	 * @return array<string,string> Relative path => "written".
	 */
	public function add_to( Bundle $bundle ) {
		$result = array();
		foreach ( $this->files() as $path => $content ) {
			$bundle->add_string( $path, $content );
			$result[ $path ] = 'written';
		}
		return $result;
	}

	/**
	 * rsync exclude patterns: never copied from the repository into the build,
	 * never deployed, never deleted on the server.
	 */
	private function deployignore() {
		$content = $this->site->relative( $this->site->content_dir );
		$plugins = $this->site->relative( $this->site->plugins_dir );
		$themes  = $this->site->relative( $this->site->themes_dir );

		$lines = array(
			// TODO: no visible credit and no "generated" text on purpose (see is_generated()).
			'# rsync exclude patterns (anchored at the WordPress root). Matching paths are',
			'# never copied from the repository into the build, never deployed, and never',
			'# deleted on the server, even with DEPLOY_DELETE=mirror. Edit freely.',
			'',
			'# Server configuration and state',
			'/wp-config.php',
			'/.htaccess',
			'/.user.ini',
			'/.git-ftp.log',
			'/php.ini',
			'/.well-known/',
			'/' . $content . '/uploads/',
			'/' . $content . '/cache/',
			'/' . $content . '/upgrade/',
			'/' . $content . '/upgrade-temp-backup/',
			'/' . $content . '/wflogs/',
			'/' . $content . '/ai1wm-backups/',
			'/' . $content . '/database/',
			'',
			'# Zips made for the repository only',
			'/' . $plugins . '/*.zip',
			'/' . $themes . '/*.zip',
			'',
			'/.maintenance',
			'',
			'# Never deployed: secrets, dumps, logs, editor and OS files, dependencies',
			'.env',
			'.env.*',
			'*.sql',
			'*.sql.gz',
			'*.log',
			'.DS_Store',
			'Thumbs.db',
			'.idea/',
			'.vscode/',
			'node_modules/',
			'',
			'# Repository and local tooling',
			'/.git/',
			'/deploy/',
			'/.github/',
			'/.gitlab-ci.yml',
			'/bitbucket-pipelines.yml',
			'/blueprint.json',
			'/' . $this->vendor_path . '/',
		);

		if ( $this->protected ) {
			$lines[] = '';
			$lines[] = '# Files packages write at runtime (known differences)';
			$lines   = array_merge( $lines, $this->protected );
		}

		/*
		 * No WordPress Studio entries on purpose: the deploy runs in the CI, from a build made of the
		 * blueprint and the repository (which never holds Studio's files), so there is nothing of Studio's
		 * to keep out. TODO: if a deploy from a Studio working tree is ever wanted, list its files here
		 * (see Kept::STUDIO).
		 */

		return implode( "\n", $lines ) . "\n";
	}
}
